statement:
You are given two integers `n` and `start`. Return a list `p` that contains every integer from `0` to `2^n - 1` exactly once and satisfies:

- `p[0]` equals `start`;
- each pair of neighbouring entries `p[i]` and `p[i + 1]` differs in exactly one bit of their binary forms;
- the last entry and the first entry also differ in exactly one bit, so the list closes into a cycle.

Many lists meet these rules; any one of them is accepted.

checker:
function check(input, actual, expected) {
  const [n, start] = input;
  const total = 1 << n;
  if (!Array.isArray(actual) || actual.length !== total || actual[0] !== start) return false;
  const seen = new Set();
  const oneBit = (a, b) => { const diff = a ^ b; return diff !== 0 && (diff & (diff - 1)) === 0; };
  for (let i = 0; i < total; i++) {
    const value = actual[i];
    if (!Number.isInteger(value) || value < 0 || value >= total || seen.has(value)) return false;
    seen.add(value);
    if (!oneBit(value, actual[(i + 1) % total])) return false;
  }
  return true;
}

validator:
function validate([n, start]) {
  if (!Number.isInteger(n) || n < 1 || n > 15) return 'n is an integer from 1 to 15 here (the n = 16 answer is too large to show).';
  if (!Number.isInteger(start) || start < 0 || start >= (1 << n)) return 'start must be between 0 and 2^n - 1.';
  return null;
}

