function circularPermutation(n, start) {
  const total = 1 << n;
  const result = [];
  for (let i = 0; i < total; i++) {
    const gray = i ^ (i >> 1);
    result.push(start ^ gray);
  }
  return result;
}

brute:
function circularPermutation(n, start) {
  // Build a Gray code by reflection, then rotate it so that it begins at start.
  let codes = [0];
  for (let width = 1; width <= n; width++) {
    const top = Math.pow(2, width - 1);
    const mirrored = [];
    for (let k = codes.length - 1; k >= 0; k--) mirrored.push(codes[k] + top);
    codes = codes.concat(mirrored);
  }
  const at = codes.indexOf(start);
  return codes.slice(at).concat(codes.slice(0, at));
}

